create table if not exists public.external_market_listings (
  id uuid primary key default gen_random_uuid(), country_code char(2) not null, country_name text not null, city text, title text not null, asset_type text not null, price_amount numeric(20,2), currency char(3), area_sqm numeric(18,2), rooms integer, summary text, source_name text not null, source_url text not null, listed_at date, checked_at date not null default current_date, active boolean not null default true, created_at timestamptz not null default now());
create index if not exists external_market_listings_country_idx on public.external_market_listings(country_code, active);
create index if not exists external_market_listings_checked_idx on public.external_market_listings(checked_at desc);
alter table public.external_market_listings enable row level security;
drop policy if exists "Public can read active external market listings" on public.external_market_listings;
create policy "Public can read active external market listings" on public.external_market_listings for select to anon, authenticated using (active = true);
grant select on public.external_market_listings to anon, authenticated;
